INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES ("カリン", "2030/01/01 14:59:59", -416.5, 20047, 53, "2023/11/16 15:00:00", 2, 2, 20047002, 3.099, 1, 0.0, "ミッションをクリアして、\n報酬をゲットしましょう！", 190801);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES ("カリン", "2030/01/01 14:59:59", -416.5, 20047, 54, "2023/11/16 15:00:00", 2, 3, 20047003, 2.801, 1, 0.0, "受け取ることができる\n報酬があるようです\n確認してみてください", 190801);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES ("カリン", "2030/01/01 14:59:59", -416.5, 20047, 54, "2023/11/16 15:00:00", 2, 4, 20047004, 0.0, 2, 0.0, "報酬がもらえますよ！\nチェックしてみてください", 190801);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES ("カリン", "2030/01/01 14:59:59", -416.5, 20047, 57, "2023/11/16 15:00:00", 1, 5, 20047005, 0.0, 1, 0.0, "イベントお疲れ様です！\n皆さんのご活躍ぶりには\nいつも感謝しています", 190801);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES ("カリン", "2030/01/01 14:59:59", -363.0, 20047, 55, "2023/11/16 15:00:00", 2, 1, 20047006, 5.506, 1, 0.0, "ギルド管理協会です！\n討伐証をお持ちでしたら、\n報酬交換できますよ", 190801);
