INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES ("カリン", "2030/01/01 14:59:59", -363.0, 20047, 56, "2023/11/16 15:00:00", 1, 3, 20047008, 1.539, 2, 0.0, "お疲れ様でした\n討伐証の交換、\nお忘れないように！", 190801);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES ("カリン", "2030/01/01 14:59:59", -363.0, 20047, 56, "2023/11/16 15:00:00", 1, 4, 20047009, 1.875, 2, 0.0, "終わっちゃいましたねー\n討伐証は努力の証！\n報酬と交換しましょう！", 190801);
